INSERT INTO `company` (`name`, `industry`, `scale`, `headquarters`, `logo`, `intro`, `culture`, `welfare`, `website`) VALUES
('字节跳动', '互联网', '10万人以上', '北京', '🎵', '全球化互联网科技公司，以「激发创造、丰富生活」为使命，旗下拥有抖音、今日头条、飞书、TikTok 等产品，业务覆盖 150+ 国家与地区。', '始终创业、务实敢为、开放谦逊、坦诚清晰、追求极致', '三餐免费、下午茶、就近租房补贴、健身房、期权激励', 'https://www.bytedance.com'),
('阿里巴巴', '互联网/云计算', '10万人以上', '杭州', '🛒', '全球领先的电商与云计算企业，旗下淘宝天猫、阿里云、菜鸟、蚂蚁集团等，让天下没有难做的生意。', '客户第一、员工第二；因为信任、所以简单', '股票期权、iHome 购房无息贷款、免费班车、体检基金', 'https://www.alibaba.com'),
('腾讯', '互联网', '10万人以上', '深圳', '🐧', '全球领先的互联网综合服务提供商，微信与 QQ 连接十余亿用户，业务涵盖社交、游戏、金融科技、云计算与内容生态。', '用户为本，科技向善', '股票激励、免费班车、年度体检、子女福利', 'https://www.tencent.com'),
('美团', '本地生活服务', '10万人以上', '北京', '🛵', '中国领先的本地生活服务平台，覆盖外卖、到店、酒旅、出行等场景，「帮大家吃得更好，生活更好」。', '以客户为中心、正直诚信、合作共赢', '免费食堂、免费班车、股票期权、节日礼品', 'https://www.meituan.com'),
('京东', '电商/零售/物流', '10万人以上', '北京', '🐶', '以供应链为基础的技术与服务企业，自营电商与自建物流为核心，零售、科技、物流、健康多板块协同。', '客户为先、诚信、协作、感恩、拼搏、担当', '股票期权、住房保障基金、免费班车、五险一金顶格', 'https://www.jd.com'),
('网易', '互联网', '1万人以上', '杭州', '🎮', '中国领先的互联网内容与技术公司，业务涵盖游戏、音乐（网易云音乐）、有道教育、严选电商，以匠心产品著称。', '有态度的网易，网聚人的力量', '五星食堂、免费班车、股票期权、年度旅游', 'https://www.163.com'),
('百度', '互联网/AI', '1万人以上', '北京', '🔍', '全球领先的 AI 公司，拥有中国最大的搜索引擎，文心大模型引领国产 AI，业务涵盖搜索、智能云、自动驾驶。', '简单可依赖', '股票期权、免费三餐、班车、AI 培训体系', 'https://www.baidu.com'),
('拼多多', '电商', '1万人以上', '上海', '🍉', '快速发展的社交电商平台，以「多实惠、多乐趣」服务最广大消费者，跨境业务 Temu 覆盖全球市场。', '本分：诚信、专注、消费者导向', '极具竞争力的薪酬、年终奖、股票期权', 'https://www.pinduoduo.com'),
('华为', '通信/ICT', '10万人以上', '深圳', '📱', '全球领先的 ICT 基础设施与智能终端提供商，业务涵盖运营商网络、企业数字化、消费者终端、智能汽车部件与芯片。', '以客户为中心，以奋斗者为本，长期艰苦奋斗', '虚拟受限股（TUP）、外派补助、午餐补助、培训赋能', 'https://www.huawei.com'),
('小米', '消费电子/IoT', '1万人以上', '北京', '📲', '以手机、智能硬件、IoT 平台为核心的互联网公司，人车家全生态，SU7 汽车开启智能出行新篇章。', '真诚且热爱、工程师文化、和用户交朋友', '股票期权、弹性工作、产品内购、餐补', 'https://www.mi.com'),
('快手', '短视频/直播', '1万人以上', '北京', '📹', '领先的短视频与直播平台，连接亿万普通人的生活与创作，电商与本地生活业务高速增长。', '拥抱变化、简单直接、始终创业', '三餐补贴、健身房、股票期权、租房补贴', 'https://www.kuaishou.com'),
('哔哩哔哩', '视频社区', '1万人以上', '上海', '📺', '中国年轻世代高度聚集的文化社区与视频平台，涵盖动漫、游戏、知识、科技等多元内容生态。', '社区优先、bilibili 干杯、品味与热爱', '免费三餐、节日礼物、股票期权、二次元氛围', 'https://www.bilibili.com'),
('微软中国', '软件/云计算（外企）', '1万人以上', '北京', '🪟', '全球软件与云计算巨头在华分支机构，Azure 云、Office 365、GitHub 与 OpenAI 深度合作，工程师文化浓厚。', '成长型思维、多元与包容、One Microsoft', '15 天年假、弹性办公、补充医疗、英文环境', 'https://www.microsoft.com/zh-cn'),
('携程集团', '在线旅游（OTA）', '1万人以上', '上海', '✈️', '全球领先的一站式旅行服务平台，覆盖机票、酒店、度假、商旅管理，「说走就走的旅行」背后的技术引擎。', '追求完美、客户导向、Pure Trip', '免费旅游基金、股票期权、班车、下午茶', 'https://www.ctrip.com'),
('大疆创新', '无人机/机器人', '1万人以上', '深圳', '🚁', '全球无人机与智能影像系统领导者，产品覆盖航拍、农业、测绘、教育等领域，「The Future of Possible」。', '激极尽志，求真品诚', '高薪+项目奖、免费食堂、宿舍、技术氛围顶级', 'https://www.dji.com');
