-- ==================== 15 家知名企业种子 ====================

-- 历史职位关联企业 + 批次
UPDATE `job` j INNER JOIN `company` c ON j.company_name = c.name SET j.company_id = c.id;
UPDATE `job` SET recruitment_batch = 2 WHERE id IN (1, 4, 6);
UPDATE `job` SET recruitment_batch = 3 WHERE id IN (2, 7);
UPDATE `job` SET recruitment_batch = 0 WHERE id IN (3, 5);
UPDATE `job` SET view_count = 120 WHERE id = 1;

